export function createTechIconImage(iconKey, strokeColor = '#1D1912') {
  const template = TECH_SVG_TEMPLATES[iconKey];
  if (!template) return null;
  const processedTemplate = template
    .replace(/fill="currentColor"/g, `fill="${strokeColor}"`)
    .replace(/stroke="currentColor"/g, `stroke="${strokeColor}"`);

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="${strokeColor}" stroke-width="1.8">${processedTemplate}</svg>`;
  const img = new Image();
  img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  return img;
}

